package co.edu.cinematch.core.model;
public class Usuario implements Identifiable { private String id,nombre,email,password,telefono; private Rol rol; public Usuario(){} public Usuario(String nombre,String email,String password,String telefono,Rol rol){this.nombre=nombre;this.email=email;this.password=password;this.telefono=telefono;this.rol=rol;} public String getId(){return id;}public void setId(String v){id=v;}public String getNombre(){return nombre;}public void setNombre(String v){nombre=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public String getTelefono(){return telefono;}public void setTelefono(String v){telefono=v;}public Rol getRol(){return rol;}public void setRol(Rol v){rol=v;} }
